  const modules = [['dashboard', 'Dashboard', 'PORTFOLIO'], ['properties', 'Properties'], ['partners', 'Partners'], ['tenants', 'Tenants / Rentals'], ['collections', 'Collections', 'OPERATIONS'], ['cheques', 'Cheques'], ['maintenance', 'Maintenance'], ['vendors', 'Vendors'], ['settlements', 'Partner Settlements', 'FINANCE & INSIGHTS'], ['company', 'Company Accounts'], ['additional', 'Additional Income / Expense'], ['reports', 'Reports'], ['settings', 'Settings', 'WORKSPACE']];
